mapper.select:
SELECT * FROM ( SELECT ROWNUM AS RNUM, A.* FROM ( SELECT CUSTOMER_ID, CUSTOMER_NAME, NVL2(EMAIL, EMAIL, PHONE) AS CONTACT_INFO, DECODE(CUSTOMER_TYPE, 'P', '개인', 'B', '기업') AS CUSTOMER_TYPE, FN_FORMAT_AMOUNT(CREDIT_LIMIT) AS CREDIT_LIMIT, TO_CHAR(REG_DATE, 'YYYY-MM-DD') AS REG_DATE, STATUS FROM CUSTOMERS WHERE STATUS = NVL(#{status}, STATUS)
AND UPPER(CUSTOMER_NAME) LIKE '%' || UPPER(#{customerName}) || '%'
AND CUSTOMER_TYPE = #{customerType}
ORDER BY CUSTOMER_ID DESC ) A WHERE ROWNUM <= #{endRow} ) WHERE RNUM >= #{startRow}

mapper.update:
UPDATE CUSTOMERS
SET STATUS = 'INACTIVE',
    UPD_DATE = SYSTIMESTAMP
WHERE CUSTOMER_ID = #{customerId}
  AND STATUS = 'ACTIVE'
  AND NOT EXISTS (
      SELECT 1 FROM ORDERS
      WHERE CUSTOMER_ID = #{customerId}
        AND ORDER_STATUS IN ('PENDING', 'CONFIRMED', 'SHIPPED')
  )
